short_msgs = [msg for msg in messages if len(msg) == 6]
print(f"Found {len(short_msgs)} messages of length 6:")
for msg in short_msgs:
    print(msg)

def test_matrix(x, y):
    # Create a test matrix with our guessed values
    test_matrix = M(3, 3)
    test_matrix.populate([3, 6, x,
