#!/usr/bin/env python3
from encoder import *
import ast
from itertools import product
import sys

def load_messages():
    with open('ctf_files/messages.txt', 'r') as f:
        return [ast.literal_eval(line.strip()) for line in f]

def encrypt_word(word, x, y):
    ecm = M(3, 3)
    ecm.populate([3, 6, x,
                 y, 4, 2,
                 1, 5, 7])
    e = Enc(ecm, word)
    return e.encrypt()

def check_encryption_match(encrypted, messages):
    return any(encrypted == msg for msg in messages)

def main():
    messages = load_messages()
    two_blocks = [msg for msg in messages if len(msg) == 6]
    three_blocks = [msg for msg in messages if len(msg) == 9]

    print(f"Found {len(two_blocks)} two-block messages")
    print(f"Found {len(three_blocks)} three-block messages")

    # Common short words that might appear in messages
    test_words = ['the', 'and', 'is', 'to', 'in', 'it', 'at', 'hi', 'ok', 'no']

    x_range = range(-10, 11)  # Testing x from -10 to 10
    y_range = range(-10, 11)  # Testing y from -10 to 10

    print("\nStarting matrix value search...")

    for x, y in product(x_range, y_range):
        if x % 5 == 0 and y == x_range.start:
            print(f"Testing x={x}...")
            sys.stdout.flush()

        for word in test_words:
            try:
                encrypted = encrypt_word(word, x, y)
                if check_encryption_match(encrypted, two_blocks):
                    print(f"\nPotential match found!")
                    print(f"Word: {word}")
                    print(f"x={x}, y={y}")
                    print(f"Encrypted: {encrypted}")

                    # Verify with a few more words
                    verify_words = ['we', 'me', 'go']
                    matches = []

                    for vword in verify_words:
                        v_enc = encrypt_word(vword, x, y)
                        if check_encryption_match(v_enc, two_blocks):
                            matches.append(vword)

                    if matches:
                        print(f"Additional matches: {matches}")
                    print("-" * 40)
            except Exception as e:
                continue

if __name__ == "__main__":
    print("Starting enhanced matrix solver...")
    main()

