from collections import Counter
from itertools import product
import ast
from encoder import *

def load_messages():
    with open('ctf_files/messages.txt', 'r') as f:
        return [ast.literal_eval(line.strip()) for line in f]

def chunks(lst, n):
    for i in range(0, len(lst), n):
        yield lst[i:i + n]

def find_common_blocks(messages):
    blocks = []
    for msg in messages:
        blocks.extend(tuple(block) for block in chunks(msg, 3))
    return Counter(blocks)

def analyze_patterns():
    messages = load_messages()

    # Group messages by length
    length_groups = {}
    for msg in messages:
        length = len(msg)
        if length not in length_groups:
            length_groups[length] = []
